import os, multiprocessing as mp

class Runtime:
    def __init__(self):
        self.pid = os.getpid()
    def apply(self, value):
        if self.pid != os.getpid():
            raise RuntimeError("runtime inherited across fork")
        return {"value": value * 2, "init_pid": self.pid, "pid": os.getpid(), "start_method": mp.get_start_method()}

